import{r as e}from"./rolldown-runtime-S-ySWqyJ.js";import{i as t,r as n}from"./framework-CXnKph_e.js";import{t as r}from"./i18n-DINy87yj.js";import{a as i,i as a}from"./SubpageChrome-D5rsljpB.js";var o=e(t(),1),s=n();function c({content:e,ready:t=!0,onRetry:n}){let{locale:o,theme:c,toggleLocale:l,toggleTheme:u}=i(),d=e[o]||e.es;return(0,s.jsx)(a,{locale:o,theme:c,onLocale:l,onTheme:u,children:(0,s.jsxs)(`article`,{className:`legal-page`,children:[(0,s.jsxs)(`header`,{className:`legal-hero`,children:[(0,s.jsxs)(`p`,{className:`eyebrow`,children:[(0,s.jsx)(`span`,{}),d.eyebrow]}),(0,s.jsx)(`h1`,{children:d.title}),(0,s.jsx)(`p`,{children:d.intro}),(0,s.jsxs)(`div`,{className:`legal-status`,children:[(0,s.jsx)(`strong`,{children:d.status}),(0,s.jsx)(`span`,{children:d.updated})]})]}),t?(0,s.jsxs)(`div`,{className:`legal-body`,children:[(0,s.jsxs)(`aside`,{children:[(0,s.jsx)(`span`,{children:`VD / LEGAL`}),(0,s.jsx)(`p`,{children:r(o,`Las traducciones son informativas. Si existe una diferencia, prevalece el texto en español salvo disposición legal en contrario.`,`Translations are informational. If a discrepancy exists, the Spanish text controls unless applicable law requires otherwise.`,`Vertalingen zijn informatief. Bij verschillen is de Spaanse tekst leidend, tenzij het toepasselijke recht anders voorschrijft.`,`Les traductions sont données à titre informatif. En cas de différence, le texte espagnol prévaut, sauf disposition légale contraire.`)})]}),(0,s.jsx)(`div`,{className:`legal-sections`,children:d.sections.map(e=>(0,s.jsxs)(`section`,{children:[(0,s.jsx)(`h2`,{children:e.title}),e.paragraphs?.map(e=>(0,s.jsx)(`p`,{children:e},e)),e.items&&(0,s.jsx)(`ul`,{children:e.items.map(e=>(0,s.jsx)(`li`,{children:e},e))})]},e.title))})]}):(0,s.jsxs)(`div`,{role:`status`,children:[(0,s.jsx)(`p`,{children:n?r(o,`No pudimos cargar los datos necesarios para mostrar este aviso. Inténtalo de nuevo.`,`We could not load the details needed to display this notice. Please try again.`,`De gegevens voor deze verklaring konden niet worden geladen. Probeer opnieuw.`,`Les informations nécessaires à cet avis n’ont pas pu être chargées. Réessayez.`):r(o,`Cargando el aviso…`,`Loading the notice…`,`Verklaring laden…`,`Chargement de l’avis…`)}),n&&(0,s.jsx)(`button`,{type:`button`,className:`button button-ghost`,onClick:n,children:r(o,`Volver a intentar`,`Try again`,`Opnieuw proberen`,`Réessayer`)})]})]})})}var l={privacy:{eyebrow:`Aviso integral de privacidad`,title:`El cuidado de tus datos.`,intro:`Este aviso explica qué información se trata al visitar el sitio de Vicente Diablo, solicitar una presentación o dejar una propina, para qué se utiliza y cómo puedes ejercer tus derechos.`,status:`{{status}}`,updated:`Versión del 11 de septiembre de 2026`,sections:[{title:`Responsable y medios de contacto`,paragraphs:[`{{identity}}`,`El responsable determina el uso de la información recibida por este sitio. El nombre artístico Vicente Diablo identifica al proyecto musical; la identidad de quien contrata y recibe los pagos es la indicada en este apartado y en la oferta concreta. {{availability}}`]},{title:`Información que recibimos`,paragraphs:[`Al solicitar una actuación podemos recibir tu nombre, correo electrónico, teléfono si decides proporcionarlo, ciudad y país, fecha, tipo de evento y los detalles que añadas sobre recinto, público, horario, duración, formato, sonido y presupuesto. No incluyas datos de salud, documentos de identidad ni información de otras personas que no sea necesaria para organizar el evento.`,`En los pagos conservamos una referencia de operación, importe, moneda, estado, posibles reembolsos o disputas y los datos de contacto necesarios para atender la operación. Stripe recoge y procesa los datos de pago en su propia página; nuestro formulario no solicita ni recibe el número completo de tu tarjeta.`,`Las solicitudes al servidor pueden incluir dirección IP, información del navegador y registros técnicos necesarios para entregar el sitio, limitar abusos e investigar errores. No utilizamos estos registros para crear perfiles publicitarios.`]},{title:`Para qué se utilizan`,paragraphs:[`Los datos de una solicitud se utilizan para responderte, revisar la disponibilidad, elaborar y comunicar un presupuesto y, si se alcanza un acuerdo, organizar y prestar la actuación. Los datos de pago permiten verificar el cobro, atender incidencias, gestionar reembolsos y cumplir las obligaciones que resulten aplicables.`,`No añadimos tu contacto a una lista de publicidad por enviar un formulario o apoyar la música. Cualquier finalidad promocional distinta requerirá una elección independiente cuando corresponda. No se toman decisiones automatizadas sobre tu solvencia ni sobre tu derecho a contratar. El cálculo regional aplica los costes publicados por el equipo; por sí solo no confirma una fecha.`]},{title:`Alojamiento, pagos y servicios externos`,paragraphs:[`Cloudflare presta el alojamiento y la base de datos del sitio. Stripe interviene en el procesamiento de pagos. Estos proveedores reciben la información necesaria para sus funciones, con el alcance que corresponde a su servicio y a sus propias obligaciones. Su infraestructura puede implicar tratamiento fuera del país del responsable. Las comunicaciones de datos se sujetan a la base jurídica, información y garantías exigibles; no se vende la información personal.`,`Spotify sólo se carga cuando eliges reproducir música o cuando existe una preferencia previa de activación. Al conectarse puede recibir tu dirección IP e información del navegador y aplicar sus propias tecnologías. Puedes retirar esa preferencia mediante el control de privacidad del reproductor o borrando los datos de este sitio en el navegador.`,`Los enlaces a WhatsApp y redes sociales te llevan a servicios con avisos propios. Cuando el formulario prepara un mensaje local, el sitio no guarda esa solicitud: tú decides si abres WhatsApp y la envías. Si la recepción de solicitudes está habilitada, se informa antes de enviar y la solicitud se guarda en la base de datos del sitio.`]},{title:`Preferencias y conservación`,paragraphs:[`El navegador conserva el idioma, el tema visual y tu elección de conectar el reproductor. Puedes cambiar las dos primeras desde la cabecera y retirar la tercera desde el reproductor. No se han incorporado píxeles de publicidad ni herramientas de analítica de marketing.`,`Las solicitudes cerradas se eliminan durante el mantenimiento programado cuando han transcurrido {{retention}} días desde su recepción. Una solicitud que siga abierta se mantiene mientras sea necesaria para atenderla. Los registros de pagos, contratos e incidencias se conservan durante los plazos legales aplicables y, cuando proceda, durante el tiempo necesario para formular o defender reclamaciones. El acceso se limita a las personas autorizadas.`]},{title:`Acceso, rectificación, cancelación y oposición`,paragraphs:[`Puedes solicitar acceso a tus datos, corregirlos, pedir su cancelación u oponerte a su tratamiento, así como limitar su uso o revocar un consentimiento cuando proceda. Envía tu petición al contacto de privacidad indicado arriba, identifica el derecho que deseas ejercer, describe los datos involucrados y facilita un medio para responder. Sólo se pedirá la información proporcionada que resulte necesaria para verificar tu identidad o representación; no envíes documentos de identidad sin que se te soliciten por un canal adecuado.`,`Cuando resulte aplicable la legislación mexicana de datos personales, la determinación se comunicará dentro de los veinte días hábiles previstos legalmente y, si procede, se hará efectiva dentro de los quince días hábiles siguientes. Las ampliaciones justificadas y las excepciones se comunicarán conforme a la ley. La cancelación o revocación no elimina obligaciones de conservación ni afecta retroactivamente un tratamiento lícito. Puedes acudir a la autoridad competente; en México, la Secretaría Anticorrupción y Buen Gobierno.`,`Si resulta aplicable el Reglamento General de Protección de Datos de la Unión Europea, también podrás ejercer los derechos de limitación y portabilidad en los casos previstos y presentar una reclamación ante la autoridad de control competente. Se aplicarán los plazos y garantías de esa normativa. {{privacyDetails}}`]},{title:`Cambios en este aviso`,paragraphs:[`La versión vigente estará disponible en esta dirección con su fecha de actualización. Si un cambio exige nueva información o consentimiento, se proporcionará antes de utilizar los datos para la nueva finalidad. Puedes conservar una copia del aviso y de las condiciones que aceptes.`]}]},terms:{eyebrow:`Condiciones de contratación`,title:`Cada fecha, bien acordada.`,intro:`Estas condiciones regulan las solicitudes y reservas de actuaciones de Vicente Diablo realizadas a través del sitio. La oferta de la presentación concreta completa este documento.`,status:`{{status}}`,updated:`Versión del 11 de septiembre de 2026`,sections:[{title:`Quién presta el servicio`,paragraphs:[`{{identity}}`,`La actuación se contrata con la persona o entidad identificada en la oferta, que deberá coincidir con la información facilitada antes del pago. {{availability}}`]},{title:`Solicitud y presupuesto`,paragraphs:[`Enviar una consulta no constituye una reserva, no bloquea la agenda y no autoriza cargos. El equipo revisa fecha, lugar, formato y producción antes de emitir una propuesta. Los datos que proporciones deben ser suficientes y correctos para valorar el evento.`,`El cálculo por región utiliza honorarios y costes confirmados por el equipo: duración incluida, tiempo adicional prorrateado por minuto, viaje redondo por persona, alojamiento por habitación y noche, viáticos por persona y día, traslados e impuesto configurado. No es una consulta en tiempo real a aerolíneas ni una tarifa de transporte garantizada fuera de su vigencia. Un presupuesto orientativo requiere confirmar disponibilidad, recinto y condiciones antes de reservar.`]},{title:`Contenido de la oferta y precio`,paragraphs:[`Antes de una reserva de pago inmediato se muestran el formato, la fecha, la hora y su zona horaria, ciudad, duración, precio total en pesos mexicanos (MXN) y las condiciones particulares. La descripción debe precisar el alcance de la actuación, la ubicación, la producción necesaria y las responsabilidades del organizador y del prestador.`,`El precio total de una fecha publicada comprende lo indicado en esa oferta. Si se calculó con una tarifa regional, se conserva su desglose aunque posteriormente cambie la tarifa. No se añadirán después gastos de viaje, producción u otros servicios sin informar su importe y obtener un acuerdo expreso. Los impuestos y cargos incluidos se muestran antes de pagar. Una conversión o comisión aplicada por el banco del cliente debe consultarse con esa entidad.`,`La reserva inmediata de este sitio cobra el total de la presentación. No se ofrece un anticipo o saldo distinto salvo que exista una propuesta expresa y un medio de pago que lo identifique. Los datos fiscales y la emisión de comprobantes se atienden a través del contacto del prestador según la legislación que resulte aplicable.`]},{title:`Reserva y confirmación del pago`,paragraphs:[`Sólo puede reservarse de forma inmediata una presentación que siga disponible al iniciar la operación. Al abrir el pago, el sistema retiene temporalmente esa fecha. La retención no equivale a confirmación y puede caducar si el pago no se completa.`,`La reserva se confirma cuando el servidor verifica el pago con el procesador y conserva la asignación de la fecha. Un regreso al sitio, una captura de pantalla o un mensaje del navegador no prueban por sí solos la recepción del importe. Si el estado requiere revisión, contacta al equipo con la referencia de operación antes de intentar un nuevo cargo.`,`El servicio de pago puede pedir autenticación adicional al titular. El sitio no garantiza que todos los dispositivos permitan pagar con un único gesto. Las operaciones duplicadas, erróneas o no reconocidas se revisarán con el prestador y el procesador, sin perjuicio de los derechos que correspondan frente a la entidad financiera.`]},{title:`Cambios, cancelación e incumplimiento`,paragraphs:[`Las reglas particulares sobre cambio de fecha, cancelación, devolución y producción deben constar en la oferta antes de pagar. Si el lugar, horario, duración o formato cambian, cualquier ajuste de precio o disponibilidad requiere acuerdo de ambas partes; ninguna modificación se considera aceptada por el mero silencio del cliente.`,`Ante una imposibilidad de prestar la actuación, el equipo informará la situación y las soluciones que correspondan según lo contratado y la ley, incluida, cuando proceda, la devolución del importe. Una cláusula particular no puede suprimir derechos irrenunciables del consumidor ni excluir de forma general toda responsabilidad del prestador.`,`Las peticiones de cancelación o reembolso se dirigirán al contacto indicado con la referencia de reserva. El plazo efectivo del abono puede depender del procesador y de la entidad emisora. No se considerará concluido un reembolso hasta verificar su estado. Los derechos de revocación o desistimiento que resulten legalmente aplicables se respetan con su alcance y excepciones, atendiendo al país, al servicio y a la fecha contratados.`]},{title:`Uso del sitio y materiales musicales`,paragraphs:[`Puedes utilizar el sitio para escuchar mediante los servicios integrados, consultar información y gestionar una solicitud. Los derechos sobre fotografías, grabaciones, composiciones y otros materiales pertenecen a sus respectivos titulares. La visita o contratación de una actuación no concede por sí misma licencias de reproducción, sincronización, retransmisión o explotación comercial.`,`No se permite interferir con el servicio, introducir datos ajenos sin autorización ni intentar acceder a la administración. La atención de una incidencia técnica no limita los derechos que deriven de una contratación ya confirmada.`]},{title:`Atención y normativa aplicable`,paragraphs:[`Las incidencias se atenderán a través del contacto del prestador. Conserva la oferta aceptada, la referencia de operación y las comunicaciones relacionadas con tu evento. Las condiciones se interpretan conforme a la legislación que corresponda a la operación; no se impone una renuncia a la protección del consumidor ni a la competencia de una autoridad que sea obligatoria por ley.`,`Las traducciones facilitan la lectura. En caso de discrepancia se atenderá al texto en español y a la oferta aceptada, sin perjuicio de las normas imperativas sobre idioma, transparencia o contratación que resulten aplicables.`]}]},support:{eyebrow:`Condiciones del apoyo`,title:`Una propina por su música.`,intro:`Si disfrutaste la música que Vicente comparte, puedes dejar una propina voluntaria. Tú eliges el importe y decides si quieres pagar.`,status:`{{status}}`,updated:`Versión del 11 de septiembre de 2026`,sections:[{title:`Destinatario y naturaleza del pago`,paragraphs:[`{{identity}}`,`El pago es una propina por la música o el contenido ya ofrecidos. No compra una actuación futura, reserva, membresía, inversión ni derecho sobre el proyecto. No se anuncia como donativo benéfico ni como aportación deducible de impuestos. {{availability}}`]},{title:`Importe y autorización`,paragraphs:[`Los botones indican importes en pesos mexicanos (MXN) y abren la página de pago correspondiente. También puedes elegir otro importe dentro de los límites mostrados. Antes de autorizar, revisa destinatario, moneda y total. El pago es único; no se crea una suscripción ni se autorizan cargos periódicos.`,`Stripe procesa el pago. Las tarjetas y monederos disponibles dependen de la cuenta, el dispositivo y el país; el procesador o el banco pueden pedir una confirmación adicional. Un solo toque en el sitio abre el cobro, pero no sustituye la autorización exigida al titular.`]},{title:`Errores, duplicados y devoluciones`,paragraphs:[`Si pagaste por error, observas una duplicidad o necesitas revisar la operación, contacta al destinatario con la referencia, la fecha y el importe. No envíes datos completos de tarjeta. El equipo verificará el caso y tramitará la devolución que proceda conforme a las circunstancias y la legislación aplicable.`,`{{supportTerms}}`,`Una confirmación visual no acredita por sí sola un pago o un reembolso. El estado se verifica con el procesador. Los tiempos de recepción de una devolución pueden depender del banco o del medio utilizado.`]},{title:`Datos personales`,paragraphs:[`La información necesaria para gestionar el pago y atender incidencias se trata conforme al aviso de privacidad del sitio y a la información del procesador. Dejar una propina no te suscribe a publicidad ni obliga a contratar otros servicios.`]}]}},u={privacy:{eyebrow:`Full privacy notice`,title:`Taking care of your data.`,intro:`This notice explains what information is processed when you visit Vicente Diablo’s website, request a performance or leave a tip, how it is used and how you can exercise your rights.`,status:`{{status}}`,updated:`Version dated 11 September 2026`,sections:[{title:`Data controller and contact details`,paragraphs:[`{{identity}}`,`The data controller determines how information received through this website is used. The stage name Vicente Diablo identifies the music project; the identity of the party entering into the contract and receiving payments is stated in this section and in the specific offer. {{availability}}`]},{title:`Information we receive`,paragraphs:[`When you request a performance, we may receive your name, email address, phone number if you choose to provide it, city and country, date, type of event and any details you add about the venue, audience, schedule, duration, format, sound and budget. Do not include health information, identity documents or information about other people that is not necessary to organise the event.`,`For payments, we retain a transaction reference, amount, currency, status, any refunds or disputes, and the contact details needed to handle the transaction. Stripe collects and processes payment details on its own page; our form does not request or receive your full card number.`,`Requests to the server may include an IP address, browser information and technical logs needed to deliver the website, limit abuse and investigate errors. We do not use these logs to build advertising profiles.`]},{title:`How the information is used`,paragraphs:[`Information in a request is used to reply to you, check availability, prepare and communicate a quote and, if an agreement is reached, organise and deliver the performance. Payment information allows us to verify payment, address issues, manage refunds and meet any applicable obligations.`,`We do not add your contact details to a marketing list because you submit a form or support the music. Any separate promotional purpose will require an independent choice where applicable. No automated decisions are made about your creditworthiness or your right to enter into a contract. The regional calculation applies the costs published by the team; it does not, on its own, confirm a date.`]},{title:`Hosting, payments and external services`,paragraphs:[`Cloudflare provides the website’s hosting and database. Stripe is involved in processing payments. These providers receive the information needed for their functions, within the scope of their service and their own obligations. Their infrastructure may involve processing outside the data controller’s country. Data disclosures are subject to the required legal basis, information and safeguards; personal information is not sold.`,`Spotify is loaded only when you choose to play music or when you have previously opted to enable it. When connected, it may receive your IP address and browser information and use its own technologies. You can withdraw that preference using the player’s privacy control or by clearing this website’s data in your browser.`,`Links to WhatsApp and social media take you to services with their own notices. When the form prepares a message locally, the website does not save that request: you decide whether to open WhatsApp and send it. If request submission is enabled, you are informed before sending, and the request is saved in the website’s database.`]},{title:`Preferences and retention`,paragraphs:[`Your browser stores your language, visual theme and choice to connect the player. You can change the first two in the header and withdraw the third in the player. No advertising pixels or marketing analytics tools have been added.`,`Closed requests are deleted during scheduled maintenance once {{retention}} days have passed since they were received. A request that remains open is retained for as long as necessary to handle it. Payment, contract and issue records are kept for the applicable statutory periods and, where appropriate, for as long as necessary to bring or defend claims. Access is restricted to authorised people.`]},{title:`Access, rectification, cancellation and objection`,paragraphs:[`You may request access to your data, correct it, request its cancellation or object to its processing, as well as limit its use or withdraw consent where applicable. Send your request to the privacy contact listed above, identify the right you wish to exercise, describe the data involved and provide a way for us to reply. We will request only such information as is necessary to verify your identity or authority to act as a representative; do not send identity documents unless asked to do so through an appropriate channel.`,`Where Mexican personal data legislation applies, the decision will be communicated within the statutory period of twenty business days and, if the request is granted, implemented within the following fifteen business days. Justified extensions and exceptions will be communicated in accordance with the law. Cancellation or withdrawal of consent does not remove retention obligations or retroactively affect lawful processing. You may contact the competent authority; in Mexico, this is the Secretaría Anticorrupción y Buen Gobierno (Secretariat for Anti-Corruption and Good Governance).`,`If the European Union’s General Data Protection Regulation applies, you may also exercise the rights to restriction and portability in the cases provided for and lodge a complaint with the competent supervisory authority. The time limits and safeguards under that regulation will apply. {{privacyDetails}}`]},{title:`Changes to this notice`,paragraphs:[`The current version will be available at this address with its update date. If a change requires new information or consent, this will be provided or obtained before the data is used for the new purpose. You may keep a copy of the notice and of the terms you accept.`]}]},terms:{eyebrow:`Booking terms`,title:`Every date, clearly agreed.`,intro:`These terms govern requests and bookings for Vicente Diablo performances made through the website. The offer for the specific performance supplements this document.`,status:`{{status}}`,updated:`Version dated 11 September 2026`,sections:[{title:`Who provides the service`,paragraphs:[`{{identity}}`,`The performance is contracted with the person or entity identified in the offer, whose identity must match the information provided before payment. {{availability}}`]},{title:`Enquiries and quotes`,paragraphs:[`Sending an enquiry does not constitute a booking, hold a date in the calendar or authorise any charges. The team reviews the date, location, format and production requirements before issuing a proposal. The information you provide must be sufficient and accurate to assess the event.`,`The regional calculation uses fees and costs confirmed by the team: included duration, additional time charged proportionally by the minute, return travel per person, accommodation per room per night, daily allowances per person per day, transfers and the configured tax. It is not a real-time airline enquiry or a transport fare guaranteed beyond its validity period. An indicative quote requires confirmation of availability, venue and conditions before booking.`]},{title:`Offer details and price`,paragraphs:[`Before an immediate-payment booking, the format, date, time and time zone, city, duration, total price in Mexican pesos (MXN) and specific conditions are displayed. The description must specify the scope of the performance, location, production requirements and the responsibilities of the organiser and service provider.`,`The total price for a listed date covers what is stated in that offer. If it was calculated using a regional rate, its breakdown is retained even if the rate later changes. Travel, production or other service costs will not be added afterwards without disclosing the amount and obtaining express agreement. Included taxes and charges are displayed before payment. Any currency conversion or fee applied by the customer’s bank should be checked with that institution.`,`An instant booking through this website charges the full performance price. No different deposit or balance arrangement is offered unless there is an express proposal and a payment method that identifies it. Tax details and the issuing of supporting documents are handled through the service provider’s contact in accordance with the applicable legislation.`]},{title:`Booking and payment confirmation`,paragraphs:[`Only a performance that remains available when the transaction starts can be booked instantly. When you open the payment page, the system temporarily holds that date. A hold is not a confirmation and may expire if payment is not completed.`,`The booking is confirmed when the server verifies payment with the processor and retains the allocation of the date. Returning to the website, a screenshot or a browser message does not, on its own, prove receipt of the amount. If the status requires review, contact the team with the transaction reference before attempting another charge.`,`The payment service may ask the holder for additional authentication. The website does not guarantee that all devices allow payment with a single gesture. Duplicate, incorrect or unrecognised transactions will be reviewed with the service provider and processor, without prejudice to any rights against the financial institution.`]},{title:`Changes, cancellation and failure to perform`,paragraphs:[`Specific rules on rescheduling, cancellation, refunds and production must be included in the offer before payment. If the location, schedule, duration or format changes, any adjustment to the price or availability requires agreement by both parties; no change is considered accepted merely because the customer remains silent.`,`If the performance cannot be provided, the team will explain the situation and the remedies available under the agreement and the law, including a refund where applicable. A specific clause cannot remove a consumer’s non-waivable rights or generally exclude all liability of the service provider.`,`Cancellation or refund requests must be sent to the listed contact with the booking reference. The time it takes for the funds to be credited may depend on the processor and the issuing institution. A refund will not be considered complete until its status has been verified. Any legally applicable rights to revoke consent to the transaction or withdraw from the contract will be respected within their scope and exceptions, taking account of the country, service and date covered by the contract.`]},{title:`Use of the website and music materials`,paragraphs:[`You may use the website to listen through the integrated services, view information and manage an enquiry. Rights in photographs, recordings, compositions and other materials belong to their respective holders. Visiting the website or booking a performance does not, in itself, grant licences for reproduction, synchronisation, rebroadcasting or commercial exploitation.`,`Interfering with the service, entering other people’s data without authorisation or attempting to access the administration area is not permitted. The handling of a technical issue does not limit the rights arising from an already confirmed booking.`]},{title:`Support and applicable law`,paragraphs:[`Issues will be handled through the service provider’s contact. Keep the accepted offer, transaction reference and communications relating to your event. These terms are interpreted in accordance with the law applicable to the transaction; they do not impose a waiver of consumer protection or of an authority’s jurisdiction where that jurisdiction is mandatory by law.`,`Translations are provided for ease of reading. In the event of a discrepancy, the Spanish text and the accepted offer will be taken into account, without prejudice to any applicable mandatory rules on language, transparency or contracting.`]}]},support:{eyebrow:`Support terms`,title:`A tip for his music.`,intro:`If you enjoyed the music Vicente shares, you can leave a voluntary tip. You choose the amount and decide whether to pay.`,status:`{{status}}`,updated:`Version dated 11 September 2026`,sections:[{title:`Recipient and nature of the payment`,paragraphs:[`{{identity}}`,`The payment is a tip for music or content already provided. It does not purchase a future performance, booking, membership, investment or rights in the project. It is not advertised as a charitable donation or a tax-deductible contribution. {{availability}}`]},{title:`Amount and authorisation`,paragraphs:[`The buttons display amounts in Mexican pesos (MXN) and open the corresponding payment page. You may also choose another amount within the displayed limits. Before authorising payment, check the recipient, currency and total. This is a one-off payment; no subscription is created and no recurring charges are authorised.`,`Stripe processes the payment. Available cards and digital wallets depend on the account, device and country; the processor or bank may ask for additional confirmation. A single tap on the website opens the payment page, but does not replace the authorisation required from the holder.`]},{title:`Errors, duplicates and refunds`,paragraphs:[`If you paid by mistake, notice a duplicate or need a transaction reviewed, contact the recipient with the reference, date and amount. Do not send full card details. The team will verify the case and process any refund that is appropriate under the circumstances and applicable law.`,`{{supportTerms}}`,`A visual confirmation does not, on its own, establish that a payment or refund has been made. Its status is verified with the processor. The time it takes to receive a refund may depend on the bank or payment method used.`]},{title:`Personal data`,paragraphs:[`Information needed to manage the payment and address issues is processed in accordance with the website’s privacy notice and the information provided by the processor. Leaving a tip does not subscribe you to marketing or require you to purchase other services.`]}]}},d={privacy:{eyebrow:`Volledige privacyverklaring`,title:`Zorg voor je gegevens.`,intro:`Deze verklaring legt uit welke informatie wordt verwerkt wanneer je de website van Vicente Diablo bezoekt, een optreden aanvraagt of een fooi geeft, waarvoor die informatie wordt gebruikt en hoe je je rechten kunt uitoefenen.`,status:`{{status}}`,updated:`Versie van 11 september 2026`,sections:[{title:`Verwerkingsverantwoordelijke en contactgegevens`,paragraphs:[`{{identity}}`,`De verwerkingsverantwoordelijke bepaalt hoe de informatie die via deze website wordt ontvangen, wordt gebruikt. De artiestennaam Vicente Diablo verwijst naar het muziekproject; de identiteit van degene die de overeenkomst sluit en de betalingen ontvangt, staat in dit onderdeel en in het concrete aanbod. {{availability}}`]},{title:`Informatie die we ontvangen`,paragraphs:[`Wanneer je een optreden aanvraagt, kunnen we je naam, e-mailadres, telefoonnummer als je dat wilt opgeven, stad en land, datum, soort evenement en aanvullende informatie over de locatie, het publiek, de planning, de duur, de vorm van het optreden, het geluid en het budget ontvangen. Voeg geen gezondheidsgegevens, identiteitsdocumenten of informatie over andere personen toe die niet nodig is om het evenement te organiseren.`,`Bij betalingen bewaren we een transactiereferentie, het bedrag, de valuta, de status, eventuele terugbetalingen of betwistingen en de contactgegevens die nodig zijn om de transactie af te handelen. Stripe verzamelt en verwerkt de betaalgegevens op zijn eigen pagina; ons formulier vraagt niet om je volledige kaartnummer en ontvangt dit ook niet.`,`Verzoeken aan de server kunnen een IP-adres, browserinformatie en technische loggegevens bevatten die nodig zijn om de website aan te bieden, misbruik te beperken en fouten te onderzoeken. We gebruiken deze loggegevens niet om advertentieprofielen op te stellen.`]},{title:`Waarvoor de informatie wordt gebruikt`,paragraphs:[`De gegevens uit een aanvraag worden gebruikt om je te antwoorden, de beschikbaarheid te controleren, een offerte op te stellen en door te geven en, als er een overeenkomst tot stand komt, het optreden te organiseren en uit te voeren. Betaalgegevens maken het mogelijk om de betaling te verifiëren, problemen af te handelen, terugbetalingen te beheren en aan toepasselijke verplichtingen te voldoen.`,`We voegen je contactgegevens niet toe aan een marketinglijst omdat je een formulier verstuurt of de muziek steunt. Voor een ander promotioneel doel wordt waar nodig een afzonderlijke keuze gevraagd. Er worden geen geautomatiseerde beslissingen genomen over je kredietwaardigheid of je recht om een overeenkomst te sluiten. De regionale berekening gebruikt de kosten die het team heeft gepubliceerd; deze berekening bevestigt op zichzelf geen datum.`]},{title:`Hosting, betalingen en externe diensten`,paragraphs:[`Cloudflare verzorgt de hosting en de database van de website. Stripe is betrokken bij de verwerking van betalingen. Deze dienstverleners ontvangen de informatie die nodig is voor hun taken, binnen de reikwijdte van hun dienstverlening en hun eigen verplichtingen. Hun infrastructuur kan met zich meebrengen dat gegevens buiten het land van de verwerkingsverantwoordelijke worden verwerkt. Voor het verstrekken van gegevens gelden de vereiste rechtsgrondslag, informatie en waarborgen; persoonsgegevens worden niet verkocht.`,`Spotify wordt alleen geladen wanneer je ervoor kiest muziek af te spelen of wanneer je eerder hebt gekozen om de speler te activeren. Bij het maken van de verbinding kan Spotify je IP-adres en browserinformatie ontvangen en zijn eigen technologieën gebruiken. Je kunt die voorkeur intrekken via de privacybediening van de speler of door de gegevens van deze website in je browser te wissen.`,`Links naar WhatsApp en sociale media brengen je naar diensten met hun eigen verklaringen. Wanneer het formulier lokaal een bericht voorbereidt, slaat de website die aanvraag niet op: jij bepaalt of je WhatsApp opent en het bericht verstuurt. Als het ontvangen van aanvragen is ingeschakeld, word je daar vóór het versturen over geïnformeerd en wordt de aanvraag opgeslagen in de database van de website.`]},{title:`Voorkeuren en bewaartermijnen`,paragraphs:[`Je browser bewaart je taal, het visuele thema en je keuze om verbinding te maken met de speler. Je kunt de eerste twee bovenaan de pagina wijzigen en de derde via de speler intrekken. Er zijn geen advertentiepixels of tools voor marketinganalyse toegevoegd.`,`Afgesloten aanvragen worden tijdens gepland onderhoud verwijderd zodra er {{retention}} dagen zijn verstreken sinds de ontvangst. Een aanvraag die nog openstaat, blijft bewaard zolang dat nodig is voor de afhandeling. Gegevens over betalingen, overeenkomsten en problemen worden gedurende de toepasselijke wettelijke termijnen bewaard en, waar van toepassing, zolang dat nodig is om vorderingen in te stellen of ons daartegen te verdedigen. Alleen bevoegde personen hebben toegang.`]},{title:`Inzage, rectificatie, verwijdering en bezwaar`,paragraphs:[`Je kunt inzage in je gegevens vragen, ze laten corrigeren, om verwijdering verzoeken of bezwaar maken tegen de verwerking. Ook kun je waar van toepassing het gebruik beperken of toestemming intrekken. Stuur je verzoek naar het hierboven vermelde privacycontact, geef aan welk recht je wilt uitoefenen, beschrijf de betrokken gegevens en vermeld hoe we je kunnen antwoorden. We vragen alleen om informatie die nodig is om je identiteit of vertegenwoordigingsbevoegdheid te controleren; stuur geen identiteitsdocumenten tenzij daarom via een geschikt kanaal wordt gevraagd.`,`Wanneer de Mexicaanse wetgeving inzake persoonsgegevens van toepassing is, wordt de beslissing binnen de wettelijke termijn van twintig werkdagen meegedeeld en, als het verzoek wordt ingewilligd, binnen de daaropvolgende vijftien werkdagen uitgevoerd. Gerechtvaardigde verlengingen en uitzonderingen worden overeenkomstig de wet meegedeeld. Verwijdering of intrekking van toestemming heft bewaarplichten niet op en heeft geen terugwerkende kracht voor rechtmatige verwerking. Je kunt je tot de bevoegde autoriteit wenden; in Mexico is dat de Secretaría Anticorrupción y Buen Gobierno (het ministerie voor corruptiebestrijding en goed bestuur).`,`Als de Algemene verordening gegevensbescherming van de Europese Unie van toepassing is, kun je in de daarin bepaalde gevallen ook je rechten op beperking en gegevensoverdraagbaarheid uitoefenen en een klacht indienen bij de bevoegde toezichthoudende autoriteit. De termijnen en waarborgen van die verordening zijn dan van toepassing. {{privacyDetails}}`]},{title:`Wijzigingen in deze verklaring`,paragraphs:[`De actuele versie is op dit adres beschikbaar, met de datum van bijwerking. Als een wijziging nieuwe informatie of toestemming vereist, wordt die informatie verstrekt of die toestemming verkregen voordat de gegevens voor het nieuwe doel worden gebruikt. Je kunt een kopie bewaren van de verklaring en van de voorwaarden die je accepteert.`]}]},terms:{eyebrow:`Boekingsvoorwaarden`,title:`Elke datum, duidelijk afgesproken.`,intro:`Deze voorwaarden gelden voor aanvragen en boekingen van optredens van Vicente Diablo via de website. Het aanbod voor het concrete optreden vormt een aanvulling op dit document.`,status:`{{status}}`,updated:`Versie van 11 september 2026`,sections:[{title:`Wie de dienst verleent`,paragraphs:[`{{identity}}`,`De overeenkomst voor het optreden wordt gesloten met de persoon of entiteit die in het aanbod is vermeld. Die identiteit moet overeenkomen met de informatie die vóór de betaling is verstrekt. {{availability}}`]},{title:`Aanvraag en offerte`,paragraphs:[`Het versturen van een aanvraag is geen boeking, houdt geen datum in de agenda vast en geeft geen toestemming voor afschrijvingen. Het team beoordeelt de datum, locatie, vorm van het optreden en productievereisten voordat het een voorstel doet. De informatie die je verstrekt, moet voldoende en juist zijn om het evenement te kunnen beoordelen.`,`De regionale berekening gebruikt honoraria en kosten die door het team zijn bevestigd: inbegrepen duur, extra tijd naar rato per minuut, retourreis per persoon, verblijf per kamer per nacht, dagvergoeding per persoon per dag, transfers en de ingestelde belasting. Het is geen realtime zoekopdracht bij luchtvaartmaatschappijen en geen vervoertarief dat buiten zijn geldigheidsduur wordt gegarandeerd. Bij een indicatieve offerte moeten beschikbaarheid, locatie en voorwaarden worden bevestigd voordat je boekt.`]},{title:`Inhoud van het aanbod en prijs`,paragraphs:[`Vóór een boeking met directe betaling worden de vorm van het optreden, datum, tijd en tijdzone, stad, duur, totaalprijs in Mexicaanse pesos (MXN) en bijzondere voorwaarden getoond. De beschrijving moet de omvang van het optreden, de locatie, de benodigde productie en de verantwoordelijkheden van de organisator en de dienstverlener aangeven.`,`De totaalprijs voor een gepubliceerde datum omvat wat in dat aanbod staat. Als de prijs met een regionaal tarief is berekend, blijft de uitsplitsing bewaard, ook als het tarief later verandert. Kosten voor reizen, productie of andere diensten worden niet achteraf toegevoegd zonder het bedrag bekend te maken en uitdrukkelijke instemming te verkrijgen. Inbegrepen belastingen en kosten worden vóór het betalen getoond. Vraag je bank naar een eventuele valutaomrekening of vergoeding die zij in rekening brengt.`,`Bij een directe boeking via deze website wordt de volledige prijs van het optreden in rekening gebracht. Er wordt geen andere regeling voor een aanbetaling of resterend saldo aangeboden, tenzij er een uitdrukkelijk voorstel is en een betaalwijze die dit aangeeft. Fiscale gegevens en het uitreiken van bewijsstukken worden via het contact van de dienstverlener behandeld volgens de toepasselijke wetgeving.`]},{title:`Boeking en betalingsbevestiging`,paragraphs:[`Alleen een optreden dat bij het starten van de transactie nog beschikbaar is, kan direct worden geboekt. Wanneer je de betaalpagina opent, houdt het systeem die datum tijdelijk vast. Dit is geen bevestiging en kan vervallen als de betaling niet wordt afgerond.`,`De boeking wordt bevestigd wanneer de server de betaling bij de betaalverwerker verifieert en de datum toegewezen houdt. Terugkeren naar de website, een schermafbeelding of een browserbericht bewijst op zichzelf niet dat het bedrag is ontvangen. Als de status moet worden gecontroleerd, neem dan met de transactiereferentie contact op met het team voordat je opnieuw probeert te betalen.`,`De betaaldienst kan de houder om aanvullende authenticatie vragen. De website garandeert niet dat je op alle apparaten met één handeling kunt betalen. Dubbele, onjuiste of niet-herkende transacties worden samen met de dienstverlener en de betaalverwerker onderzocht, onverminderd eventuele rechten tegenover de financiële instelling.`]},{title:`Wijzigingen, annulering en niet-nakoming`,paragraphs:[`Specifieke regels over verplaatsing, annulering, terugbetaling en productie moeten vóór het betalen in het aanbod staan. Als de locatie, planning, duur of vorm van het optreden verandert, vereist elke aanpassing van de prijs of beschikbaarheid instemming van beide partijen; een wijziging geldt niet als geaccepteerd alleen omdat de klant niet reageert.`,`Als het optreden niet kan plaatsvinden, legt het team de situatie uit en geeft het aan welke oplossingen volgens de overeenkomst en de wet van toepassing zijn, waaronder waar passend terugbetaling van het bedrag. Een bijzondere bepaling mag geen rechten van consumenten uitsluiten waarvan geen afstand kan worden gedaan en mag niet in algemene zin elke aansprakelijkheid van de dienstverlener uitsluiten.`,`Verzoeken om annulering of terugbetaling moeten met de boekingsreferentie naar het vermelde contact worden gestuurd. De tijd totdat het bedrag wordt bijgeschreven, kan afhangen van de betaalverwerker en de uitgevende instelling. Een terugbetaling wordt pas als afgerond beschouwd nadat de status ervan is geverifieerd. Wettelijk toepasselijke rechten om de instemming met de transactie in te trekken of de overeenkomst te herroepen worden geëerbiedigd binnen hun reikwijdte en uitzonderingen, rekening houdend met het land, de dienst en de overeengekomen datum.`]},{title:`Gebruik van de website en muziekmateriaal`,paragraphs:[`Je mag de website gebruiken om via de geïntegreerde diensten te luisteren, informatie te bekijken en een aanvraag te beheren. Rechten op foto’s, opnamen, composities en ander materiaal behoren toe aan de respectieve rechthebbenden. Het bezoeken van de website of het boeken van een optreden verleent op zichzelf geen licenties voor reproductie, synchronisatie, heruitzending of commerciële exploitatie.`,`Het is niet toegestaan de dienst te verstoren, gegevens van anderen zonder toestemming in te voeren of te proberen toegang te krijgen tot het beheergedeelte. De afhandeling van een technisch probleem beperkt de rechten uit een al bevestigde boeking niet.`]},{title:`Contact en toepasselijke regelgeving`,paragraphs:[`Problemen worden via het contact van de dienstverlener afgehandeld. Bewaar het geaccepteerde aanbod, de transactiereferentie en de communicatie over je evenement. De voorwaarden worden uitgelegd volgens het recht dat op de transactie van toepassing is; er wordt geen afstand van consumentenbescherming opgelegd, noch van de bevoegdheid van een autoriteit wanneer die bevoegdheid wettelijk verplicht is.`,`De vertalingen zijn bedoeld om het lezen te vergemakkelijken. Bij een verschil wordt uitgegaan van de Spaanse tekst en het geaccepteerde aanbod, onverminderd toepasselijke dwingende regels over taal, transparantie of het sluiten van overeenkomsten.`]}]},support:{eyebrow:`Voorwaarden voor steun`,title:`Een fooi voor zijn muziek.`,intro:`Heb je genoten van de muziek die Vicente deelt? Dan kun je vrijwillig een fooi geven. Jij kiest het bedrag en beslist of je wilt betalen.`,status:`{{status}}`,updated:`Versie van 11 september 2026`,sections:[{title:`Ontvanger en aard van de betaling`,paragraphs:[`{{identity}}`,`De betaling is een fooi voor muziek of inhoud die al is aangeboden. Je koopt er geen toekomstig optreden, boeking, lidmaatschap, investering of rechten op het project mee. De betaling wordt niet aangeboden als gift voor een goed doel of als fiscaal aftrekbare bijdrage. {{availability}}`]},{title:`Bedrag en toestemming`,paragraphs:[`De knoppen tonen bedragen in Mexicaanse pesos (MXN) en openen de bijbehorende betaalpagina. Je kunt ook een ander bedrag kiezen binnen de getoonde grenzen. Controleer de ontvanger, valuta en het totaal voordat je toestemming geeft. De betaling is eenmalig; er wordt geen abonnement aangemaakt en je geeft geen toestemming voor periodieke afschrijvingen.`,`Stripe verwerkt de betaling. Welke kaarten en digitale portemonnees beschikbaar zijn, hangt af van het account, apparaat en land; de betaalverwerker of bank kan om een aanvullende bevestiging vragen. Met één tik op de website open je de betaalpagina, maar dat vervangt niet de toestemming die van de houder wordt vereist.`]},{title:`Fouten, dubbele betalingen en terugbetalingen`,paragraphs:[`Als je per ongeluk hebt betaald, een dubbele betaling ziet of de transactie wilt laten controleren, neem dan contact op met de ontvanger en vermeld de referentie, datum en het bedrag. Stuur geen volledige kaartgegevens. Het team controleert de situatie en verwerkt de terugbetaling die op grond van de omstandigheden en de toepasselijke wetgeving verschuldigd is.`,`{{supportTerms}}`,`Een visuele bevestiging bewijst op zichzelf niet dat een betaling of terugbetaling heeft plaatsgevonden. De status wordt bij de betaalverwerker geverifieerd. De tijd totdat je een terugbetaling ontvangt, kan afhangen van de bank of de gebruikte betaalmethode.`]},{title:`Persoonsgegevens`,paragraphs:[`De informatie die nodig is om de betaling te beheren en problemen af te handelen, wordt verwerkt volgens de privacyverklaring van de website en de informatie van de betaalverwerker. Door een fooi te geven, meld je je niet aan voor reclame en ben je niet verplicht andere diensten af te nemen.`]}]}},f={privacy:{eyebrow:`Notice de confidentialité intégrale`,title:`Prendre soin de vos données.`,intro:`Cette notice explique quelles informations sont traitées lorsque vous visitez le site de Vicente Diablo, demandez une prestation musicale ou laissez un pourboire, à quelles fins elles sont utilisées et comment exercer vos droits.`,status:`{{status}}`,updated:`Version du 11 septembre 2026`,sections:[{title:`Responsable du traitement et coordonnées`,paragraphs:[`{{identity}}`,`Le responsable du traitement détermine l’utilisation des informations reçues par ce site. Le nom de scène Vicente Diablo désigne le projet musical ; l’identité de la partie qui conclut le contrat et reçoit les paiements est indiquée dans cette rubrique et dans l’offre concernée. {{availability}}`]},{title:`Informations que nous recevons`,paragraphs:[`Lorsque vous demandez une prestation, nous pouvons recevoir votre nom, votre adresse e-mail, votre numéro de téléphone si vous choisissez de le fournir, la ville et le pays, la date, le type d’événement et les précisions que vous ajoutez sur le lieu, le public, les horaires, la durée, le format, la sonorisation et le budget. N’incluez pas de données de santé, de pièces d’identité ni d’informations sur d’autres personnes qui ne soient pas nécessaires à l’organisation de l’événement.`,`Pour les paiements, nous conservons une référence de transaction, le montant, la devise, le statut, les éventuels remboursements ou litiges et les coordonnées nécessaires au suivi de l’opération. Stripe recueille et traite les données de paiement sur sa propre page ; notre formulaire ne demande ni ne reçoit le numéro complet de votre carte.`,`Les requêtes adressées au serveur peuvent inclure une adresse IP, des informations sur le navigateur et des journaux techniques nécessaires au fonctionnement du site, à la limitation des abus et à l’analyse des erreurs. Nous n’utilisons pas ces journaux pour créer des profils publicitaires.`]},{title:`Utilisation des informations`,paragraphs:[`Les données d’une demande servent à vous répondre, vérifier les disponibilités, établir et communiquer un devis et, si un accord est conclu, organiser et assurer la prestation. Les données de paiement permettent de vérifier l’encaissement, traiter les incidents, gérer les remboursements et respecter les obligations applicables.`,`Nous n’ajoutons pas vos coordonnées à une liste publicitaire parce que vous envoyez un formulaire ou soutenez la musique. Toute autre finalité promotionnelle fera l’objet d’un choix distinct lorsque cela est requis. Aucune décision automatisée n’est prise concernant votre solvabilité ou votre droit de contracter. Le calcul régional applique les coûts publiés par l’équipe ; il ne confirme pas à lui seul une date.`]},{title:`Hébergement, paiements et services externes`,paragraphs:[`Cloudflare fournit l’hébergement et la base de données du site. Stripe intervient dans le traitement des paiements. Ces prestataires reçoivent les informations nécessaires à leurs fonctions, dans le cadre de leur service et de leurs propres obligations. Leur infrastructure peut entraîner un traitement hors du pays du responsable du traitement. Les communications de données sont soumises à la base juridique, aux informations et aux garanties requises ; les informations personnelles ne sont pas vendues.`,`Spotify ne se charge que lorsque vous choisissez d’écouter de la musique ou qu’une préférence d’activation a déjà été enregistrée. Lors de la connexion, ce service peut recevoir votre adresse IP et des informations sur votre navigateur et utiliser ses propres technologies. Vous pouvez retirer cette préférence au moyen du contrôle de confidentialité du lecteur ou en effaçant les données de ce site dans votre navigateur.`,`Les liens vers WhatsApp et les réseaux sociaux vous conduisent vers des services disposant de leurs propres notices. Lorsque le formulaire prépare un message localement, le site ne conserve pas cette demande : vous décidez d’ouvrir WhatsApp et de l’envoyer. Si la réception des demandes est activée, vous en êtes informé avant l’envoi et la demande est enregistrée dans la base de données du site.`]},{title:`Préférences et conservation`,paragraphs:[`Le navigateur conserve la langue, le thème visuel et votre choix de connecter le lecteur. Vous pouvez modifier les deux premiers dans l’en-tête et retirer le troisième dans le lecteur. Aucun pixel publicitaire ni outil d’analyse marketing n’a été intégré.`,`Les demandes clôturées sont supprimées lors de la maintenance programmée une fois que {{retention}} jours se sont écoulés depuis leur réception. Une demande encore ouverte est conservée aussi longtemps que nécessaire pour la traiter. Les enregistrements relatifs aux paiements, contrats et incidents sont conservés pendant les délais légaux applicables et, le cas échéant, aussi longtemps que nécessaire pour faire valoir ou défendre des droits en justice. L’accès est limité aux personnes autorisées.`]},{title:`Accès, rectification, effacement et opposition`,paragraphs:[`Vous pouvez demander l’accès à vos données, leur correction ou leur effacement, ou vous opposer à leur traitement, ainsi qu’en limiter l’utilisation ou retirer un consentement lorsque cela est applicable. Adressez votre demande au contact chargé de la confidentialité indiqué ci-dessus, précisez le droit que vous souhaitez exercer, décrivez les données concernées et indiquez un moyen de vous répondre. Seules les informations nécessaires à la vérification de votre identité ou de votre qualité de représentant vous seront demandées ; n’envoyez pas de pièces d’identité sans y avoir été invité par un canal approprié.`,`Lorsque la législation mexicaine sur les données personnelles s’applique, la décision est communiquée dans le délai légal de vingt jours ouvrables et, si la demande est accueillie, mise en œuvre dans les quinze jours ouvrables suivants. Les prolongations justifiées et les exceptions sont communiquées conformément à la loi. L’effacement ou le retrait du consentement ne supprime pas les obligations de conservation et n’affecte pas rétroactivement un traitement licite. Vous pouvez vous adresser à l’autorité compétente ; au Mexique, il s’agit de la Secretaría Anticorrupción y Buen Gobierno (Secrétariat à la lutte contre la corruption et à la bonne gouvernance).`,`Si le Règlement général sur la protection des données de l’Union européenne s’applique, vous pouvez également exercer les droits à la limitation et à la portabilité dans les cas prévus et introduire une réclamation auprès de l’autorité de contrôle compétente. Les délais et garanties de ce règlement s’appliquent alors. {{privacyDetails}}`]},{title:`Modifications de cette notice`,paragraphs:[`La version en vigueur sera disponible à cette adresse avec sa date de mise à jour. Si une modification nécessite de nouvelles informations ou un nouveau consentement, ces informations seront fournies ou ce consentement sera recueilli avant toute utilisation des données pour la nouvelle finalité. Vous pouvez conserver une copie de la notice et des conditions que vous acceptez.`]}]},terms:{eyebrow:`Conditions de réservation`,title:`Chaque date, clairement convenue.`,intro:`Ces conditions régissent les demandes et réservations de prestations de Vicente Diablo effectuées sur le site. L’offre relative à la prestation concernée complète ce document.`,status:`{{status}}`,updated:`Version du 11 septembre 2026`,sections:[{title:`Qui fournit le service`,paragraphs:[`{{identity}}`,`Le contrat de prestation est conclu avec la personne ou l’entité identifiée dans l’offre, dont l’identité doit correspondre aux informations fournies avant le paiement. {{availability}}`]},{title:`Demande et devis`,paragraphs:[`L’envoi d’une demande ne constitue pas une réservation, ne bloque pas l’agenda et n’autorise aucun débit. L’équipe examine la date, le lieu, le format et les besoins de production avant d’émettre une proposition. Les informations que vous fournissez doivent être suffisantes et exactes pour évaluer l’événement.`,`Le calcul par région utilise les honoraires et coûts confirmés par l’équipe : durée incluse, temps supplémentaire calculé au prorata par minute, trajet aller-retour par personne, hébergement par chambre et par nuit, indemnités journalières par personne et par jour, transferts et taxe configurée. Il ne s’agit ni d’une consultation en temps réel des compagnies aériennes ni d’un tarif de transport garanti au-delà de sa période de validité. Un devis indicatif nécessite de confirmer la disponibilité, le lieu et les conditions avant de réserver.`]},{title:`Contenu de l’offre et prix`,paragraphs:[`Avant une réservation avec paiement immédiat, le format, la date, l’heure et son fuseau horaire, la ville, la durée, le prix total en pesos mexicains (MXN) et les conditions particulières sont affichés. La description doit préciser l’étendue de la prestation, le lieu, les moyens de production nécessaires et les responsabilités de l’organisateur et du prestataire.`,`Le prix total d’une date publiée comprend ce qui est indiqué dans l’offre correspondante. S’il a été calculé à partir d’un tarif régional, sa ventilation est conservée même si le tarif change par la suite. Aucun frais de déplacement, de production ou d’autre service ne sera ajouté ultérieurement sans en communiquer le montant et obtenir un accord exprès. Les taxes et frais inclus sont affichés avant le paiement. Toute conversion ou commission appliquée par la banque du client doit être vérifiée auprès de cet établissement.`,`La réservation immédiate sur ce site entraîne le paiement de la totalité de la prestation. Aucune autre modalité d’acompte ou de solde n’est proposée, sauf en présence d’une proposition expresse et d’un moyen de paiement qui l’identifie. Les informations fiscales et l’émission de justificatifs sont traitées par l’intermédiaire du contact du prestataire, selon la législation applicable.`]},{title:`Réservation et confirmation du paiement`,paragraphs:[`Seule une prestation encore disponible au début de l’opération peut être réservée immédiatement. À l’ouverture de la page de paiement, le système bloque temporairement cette date. Ce blocage ne vaut pas confirmation et peut expirer si le paiement n’est pas finalisé.`,`La réservation est confirmée lorsque le serveur vérifie le paiement auprès du prestataire de paiement et maintient l’attribution de la date. Un retour sur le site, une capture d’écran ou un message du navigateur ne prouve pas à lui seul la réception du montant. Si le statut nécessite une vérification, contactez l’équipe avec la référence de l’opération avant de tenter un nouveau paiement.`,`Le service de paiement peut demander une authentification supplémentaire au titulaire. Le site ne garantit pas que tous les appareils permettent de payer d’un seul geste. Les opérations en double, erronées ou non reconnues seront examinées avec le prestataire et le prestataire de paiement, sans préjudice des droits pouvant être exercés auprès de l’établissement financier.`]},{title:`Modifications, annulation et inexécution`,paragraphs:[`Les règles particulières relatives au changement de date, à l’annulation, au remboursement et à la production doivent figurer dans l’offre avant le paiement. Si le lieu, les horaires, la durée ou le format changent, tout ajustement du prix ou de la disponibilité nécessite l’accord des deux parties ; aucune modification n’est considérée comme acceptée du seul fait du silence du client.`,`En cas d’impossibilité d’assurer la prestation, l’équipe expliquera la situation et les solutions applicables selon le contrat et la loi, y compris, le cas échéant, le remboursement du montant. Une clause particulière ne peut supprimer les droits du consommateur auxquels il ne peut renoncer ni exclure de manière générale toute responsabilité du prestataire.`,`Les demandes d’annulation ou de remboursement doivent être adressées au contact indiqué, avec la référence de réservation. Le délai effectif de crédit du montant peut dépendre du prestataire de paiement et de l’établissement émetteur. Un remboursement ne sera considéré comme achevé qu’après vérification de son statut. Les droits de révocation du consentement à l’opération ou de rétractation légalement applicables sont respectés dans leur portée et leurs exceptions, en tenant compte du pays, du service et de la date prévus au contrat.`]},{title:`Utilisation du site et des contenus musicaux`,paragraphs:[`Vous pouvez utiliser le site pour écouter de la musique au moyen des services intégrés, consulter des informations et gérer une demande. Les droits sur les photographies, enregistrements, compositions et autres contenus appartiennent à leurs titulaires respectifs. La visite du site ou la réservation d’une prestation n’accorde pas à elle seule de licence de reproduction, de synchronisation, de retransmission ou d’exploitation commerciale.`,`Il est interdit de perturber le service, de saisir des données appartenant à autrui sans autorisation ou de tenter d’accéder à l’espace d’administration. Le traitement d’un incident technique ne limite pas les droits découlant d’une réservation déjà confirmée.`]},{title:`Assistance et réglementation applicable`,paragraphs:[`Les incidents sont traités par l’intermédiaire du contact du prestataire. Conservez l’offre acceptée, la référence de l’opération et les communications relatives à votre événement. Les conditions sont interprétées conformément à la législation applicable à l’opération ; aucune renonciation à la protection du consommateur ni à la compétence d’une autorité imposée par la loi n’est prévue.`,`Les traductions facilitent la lecture. En cas de divergence, le texte espagnol et l’offre acceptée seront pris en compte, sans préjudice des règles impératives applicables en matière de langue, de transparence ou de conclusion des contrats.`]}]},support:{eyebrow:`Conditions du soutien`,title:`Un pourboire pour sa musique.`,intro:`Si vous avez apprécié la musique que Vicente partage, vous pouvez laisser un pourboire volontaire. Vous choisissez le montant et décidez si vous souhaitez payer.`,status:`{{status}}`,updated:`Version du 11 septembre 2026`,sections:[{title:`Destinataire et nature du paiement`,paragraphs:[`{{identity}}`,`Le paiement est un pourboire pour la musique ou les contenus déjà proposés. Il n’achète ni prestation future, ni réservation, ni adhésion, ni investissement, ni droit sur le projet. Il n’est présenté ni comme un don caritatif ni comme une contribution fiscalement déductible. {{availability}}`]},{title:`Montant et autorisation`,paragraphs:[`Les boutons indiquent des montants en pesos mexicains (MXN) et ouvrent la page de paiement correspondante. Vous pouvez également choisir un autre montant dans les limites affichées. Avant d’autoriser le paiement, vérifiez le destinataire, la devise et le total. Le paiement est unique ; aucun abonnement n’est créé et aucun débit périodique n’est autorisé.`,`Stripe traite le paiement. Les cartes et portefeuilles numériques disponibles dépendent du compte, de l’appareil et du pays ; le prestataire de paiement ou la banque peut demander une confirmation supplémentaire. Un seul appui sur le site ouvre le paiement, mais ne remplace pas l’autorisation requise du titulaire.`]},{title:`Erreurs, doublons et remboursements`,paragraphs:[`Si vous avez payé par erreur, constatez un doublon ou souhaitez faire vérifier l’opération, contactez le destinataire en indiquant la référence, la date et le montant. N’envoyez pas les données complètes de votre carte. L’équipe vérifiera la situation et traitera le remboursement qui s’impose selon les circonstances et la législation applicable.`,`{{supportTerms}}`,`Une confirmation visuelle ne prouve pas à elle seule qu’un paiement ou un remboursement a été effectué. Le statut est vérifié auprès du prestataire de paiement. Le délai de réception d’un remboursement peut dépendre de la banque ou du moyen de paiement utilisé.`]},{title:`Données personnelles`,paragraphs:[`Les informations nécessaires à la gestion du paiement et au traitement des incidents sont traitées conformément à la notice de confidentialité du site et aux informations du prestataire de paiement. Laisser un pourboire ne vous inscrit pas à des communications publicitaires et ne vous oblige pas à souscrire d’autres services.`]}]}};function p({kind:e}){let[t,n]=(0,o.useState)(null),[i,a]=(0,o.useState)(!1),[p,m]=(0,o.useState)(0);(0,o.useEffect)(()=>{let e=new AbortController;return a(!1),n(null),fetch(`/api/public/config`,{signal:AbortSignal.any([e.signal,AbortSignal.timeout(12e3)])}).then(e=>{if(!e.ok)throw Error();return e.json()}).then(t=>{e.signal.aborted||n(t)}).catch(()=>{e.signal.aborted||a(!0)}),()=>e.abort()},[p]);let h={};for(let[n,a]of Object.entries({es:l,en:u,nl:d,fr:f})){let o=n,s=t?.enabled===!0,c={identity:t?.operator?[t.operator,t.address,t.country,t.contactEmail,t.phone].filter(Boolean).join(` · `):r(o,`La identidad, domicilio y contacto del prestador están pendientes de confirmar. Se publicarán antes de habilitar solicitudes y cobros.`,`The provider’s identity, address and contact details are awaiting confirmation. They will be published before enquiries and payments are enabled.`,`De identiteit, het adres en de contactgegevens van de aanbieder moeten nog worden bevestigd. Ze worden gepubliceerd voordat aanvragen en betalingen worden ingeschakeld.`,`L’identité, l’adresse et les coordonnées du prestataire restent à confirmer. Elles seront publiées avant l’activation des demandes et paiements.`),status:t?s?r(o,`Información del prestador publicada`,`Provider information published`,`Gegevens aanbieder gepubliceerd`,`Informations du prestataire publiées`):r(o,`Recepción de solicitudes y cobros no habilitados`,`Enquiries and payments are not enabled`,`Aanvragen en betalingen zijn niet ingeschakeld`,`Demandes et paiements non activés`):i?r(o,`No pudimos consultar la información del prestador`,`Provider information could not be loaded`,`De gegevens van de aanbieder konden niet worden geladen`,`Les informations du prestataire n’ont pas pu être chargées`):r(o,`Consultando información del prestador…`,`Loading provider information…`,`Gegevens aanbieder laden…`,`Chargement des informations du prestataire…`),availability:!t||s?``:r(o,`La recepción de solicitudes y los pagos en línea permanecen deshabilitados hasta completar esta información.`,`Online enquiries and payments remain disabled until this information is complete.`,`Online aanvragen en betalingen blijven uitgeschakeld totdat deze informatie volledig is.`,`Les demandes et paiements en ligne restent désactivés jusqu’à ce que ces informations soient complètes.`),retention:String(t?.retentionDays||180),privacyDetails:t?.privacyDetails||``,supportTerms:t?.supportTerms||r(o,`Las condiciones particulares de atención se publicarán antes de habilitar las propinas.`,`Specific support arrangements will be published before tips are enabled.`,`De specifieke afspraken voor ondersteuning worden gepubliceerd voordat fooien worden ingeschakeld.`,`Les modalités particulières d’assistance seront publiées avant l’activation des pourboires.`)},l=e=>e.replace(/\{\{(\w+)\}\}/g,(e,t)=>c[t]||``).trim(),u=a[e];h[o]={...u,status:l(u.status),sections:u.sections.map(e=>({...e,paragraphs:e.paragraphs.map(l).filter(Boolean)}))}}return(0,s.jsx)(c,{content:h,ready:t!==null,onRetry:i?()=>m(e=>e+1):void 0})}export{p as BusinessLegal};